INSERT INTO ui.ui_surface_value (surface_name, name, label, description, value_type, always_available, typical_char_count, sort_order, auto_context, group_key) VALUES
('matrx-user/marketing-page', 'page_id', 'Canonical page ID', 'UUID of the `web.page` row the user has open. Always present — the route carries it.', 'string', true, 36, 300, true, 'page_identity'),
('matrx-user/marketing-page', 'page_url', 'Page URL', 'Full canonical URL of the page (e.g. https://example.com/services/). Always present once the workspace has loaded — launches only happen from a loaded workspace.', 'string', true, 80, 330, true, 'page_identity'),
('matrx-user/marketing-page', 'page_path', 'Page path', 'The site-relative path of the canonical URL (e.g. /services/). Always present — the page row always carries it; the homepage is the empty path rendered as /.', 'string', true, 30, 332, true, 'page_identity'),
('matrx-user/marketing-page', 'page_status', 'Status', 'Lifecycle status of the canonical page row (e.g. active). Reflects the page record, not the live HTTP response.', 'string', false, 10, 334, true, 'page_identity'),
('matrx-user/marketing-page', 'page_provenance', 'Provenance', 'How this canonical URL entered the system (e.g. sitemap, crawl, manual). Empty when the record predates provenance tracking.', 'string', false, 10, 336, true, 'page_identity'),
('matrx-user/marketing-page', 'first_seen', 'First seen', 'ISO timestamp of when this canonical URL was first discovered. Empty when the record predates discovery tracking.', 'string', false, 25, 338, true, 'page_identity'),
('matrx-user/marketing-page', 'last_seen', 'Last seen', 'ISO timestamp of the most recent time any collection observed this URL. Empty when never observed since tracking began.', 'string', false, 25, 339, true, 'page_identity'),
('matrx-user/marketing-page', 'target_keyword', 'Target keyword', 'The user''s primary search intent for this page (`web.page.target_keyword`). Empty when the user hasn''t set one.', 'string', false, 40, 340, true, 'page_intent'),
('matrx-user/marketing-page', 'desired_title', 'Desired meta title', 'The user''s editorial TARGET title (`web.page.meta_title_desired`) — what the title should become, distinct from what the site serves. Empty when no target is set. Agents proposing titles write candidates for THIS field.', 'string', false, 60, 500, true, 'page_intent'),
('matrx-user/marketing-page', 'desired_description', 'Desired meta description', 'The user''s editorial TARGET description (`web.page.meta_description_desired`). Empty when no target is set. Agents proposing descriptions write candidates for THIS field.', 'string', false, 160, 510, true, 'page_intent'),
('matrx-user/marketing-page', 'desired_seo_metrics', 'Desired SEO metrics', 'Deterministic metrics for the DESIRED title+description (same contract v1 shape as observed_seo_metrics). Stamped by the client on every intent save (`web.page.seo_metrics_desired`). Empty when no targets are set.', 'object', false, 700, 520, true, 'page_intent'),
('matrx-user/marketing-page', 'target_keyword_data', 'Target keyword data', 'The condensed keyword dossier for the target keyword (buildKeywordBrief over seo.keyword + keyword_market): search volume, CPC, competition, trend, and intent classification. Empty when no target keyword is set or the phrase is not in the keyword library yet.', 'object', false, 600, 525, true, 'page_intent'),
('matrx-user/marketing-page', 'page_intent', 'Page intent', 'The composite user-owned intent object: { target_keyword, desired_title, desired_description, desired_seo_metrics }. Mirrors the individual page-intent values as one group value (completeness law). Empty when the user has set none of them.', 'object', false, 1000, 530, true, 'page_intent'),
('matrx-user/marketing-page', 'desired_values', 'Desired values', 'The per-area desired-state mirror (`web.page.desired_values`): social_card, indexability (canonical/robots), headings (outline plan), image_plan, and free notes. Empty object when the user has expressed no desired state yet. Agents proposing changes to these areas write candidates for the matching key.', 'object', false, 1200, 300, true, 'authoring'),
('matrx-user/marketing-page', 'draft_content', 'Draft content', 'The user-authored draft content for this page (`web.page_content.content`, markdown) — the editorial target body, distinct from the observed captured content. Empty when no draft has been written.', 'document', false, 8000, 310, true, 'authoring'),
('matrx-user/marketing-page', 'keyword_batch', 'Keyword batch', 'The batch of keyword-library keywords attached to this page via association edges (role primary|supporting): one entry per keyword with phrase, role, search volume, and competition. The primary target_keyword rides separately in page intent. Empty array when nothing is attached.', 'array', false, 800, 320, true, 'authoring'),
('matrx-user/marketing-page', 'image_plan', 'Image plan', 'The planned images for this page (from desired_values.image_plan): per entry a description, alt text, placement, style preset (or custom style text) fed to the image pipeline, status (planned|generated|placed), and the generated image''s file_id when produced. Empty array when no images are planned.', 'array', false, 900, 330, true, 'authoring'),
('matrx-user/marketing-page', 'observed_title', 'Observed meta title', 'The <title> the live site actually served in the latest accepted snapshot. Empty when no crawl has captured this page yet, or the page has no title tag. Evidence — never invented.', 'string', false, 60, 400, true, 'observed_seo'),
('matrx-user/marketing-page', 'observed_description', 'Observed meta description', 'The meta description the live site actually served in the latest accepted snapshot. Empty when uncrawled or absent on the page. Evidence — never invented.', 'string', false, 160, 410, true, 'observed_seo'),
('matrx-user/marketing-page', 'observed_seo_metrics', 'Observed SEO metrics', 'Deterministic metrics for the OBSERVED title+description (contract v1: pixel_width, character_count, desktop_ok, mobile_ok, seo_length_ok, ok, issues[] per field + overall_ok). Stamped by the scraper at capture time (`web.snapshot.seo_metrics`). Empty when uncrawled.', 'object', false, 700, 420, true, 'observed_seo'),
('matrx-user/marketing-page', 'observed_audit_metrics', 'Observed audit metrics', 'Deterministic page-audit for the latest snapshot (contract v1: social share card, heading structure, and indexability verdict — each with ok, facts, and issues[{severity,message}]). Stamped by the scraper at capture time (`web.snapshot.audit_metrics`). Empty when uncrawled.', 'object', false, 1400, 425, true, 'observed_seo'),
('matrx-user/marketing-page', 'headings_outline', 'Headings outline', 'Ordered heading structure of the latest snapshot: one entry per heading with level (1-6) and text, exactly as the live page serves them. Empty when uncrawled or the page has no headings. Observed evidence — never invented.', 'array', false, 1500, 460, true, 'observed_seo'),
('matrx-user/marketing-page', 'http_status', 'Last HTTP status', 'HTTP status the page last returned to the crawler (e.g. 200, 301, 404). Empty when uncrawled.', 'number', false, 3, 610, true, 'observed_seo'),
('matrx-user/marketing-page', 'indexability', 'Indexability', 'Observed indexing signals from the latest snapshot''s head tags and audit: meta robots, canonical URL, redirect chain, final URL, and declared language. Empty when uncrawled.', 'object', false, 500, 620, true, 'observed_seo'),
('matrx-user/marketing-page', 'social_card', 'Social share preview', 'Observed Open Graph / Twitter share-card tags plus the deterministic evaluation issues for them. Empty when uncrawled.', 'object', false, 800, 630, true, 'observed_seo'),
('matrx-user/marketing-page', 'url_quality_issues', 'URL quality issues', 'Live deterministic URL-quality findings for the canonical URL itself (length, casing, parameters, …). Computed from the URL alone — needs no crawl. Empty array when the URL is clean.', 'array', false, 300, 640, true, 'observed_seo'),
('matrx-user/marketing-page', 'page_identity', 'Page identity', 'Observed page-identifying signals from the latest snapshot: featured image and its source, CMS/generator, WordPress or Shopify identifiers, template/platform evidence, application/site name, author, dates, schema types, locale, and related API/shortlink URLs.', 'object', false, 700, 642, true, 'observed_seo'),
('matrx-user/marketing-page', 'structured_data', 'Structured data', 'Complete structured-data evidence from the latest snapshot: every parsed and original JSON-LD script, normalized entity blocks, schema types, microdata, RDFa, microformats, and parse errors. Empty when uncrawled or the page declares none.', 'object', false, 20000, 645, false, 'observed_seo'),
('matrx-user/marketing-page', 'resources', 'Page resources', 'Complete DOM- and structured-metadata-declared resource inventory from the latest snapshot: images and responsive variants, video/audio, embeds, scripts, stylesheets, fonts, icons, manifests, tracks, and linked documents. Includes grouped counts and truncation evidence.', 'object', false, 20000, 647, false, 'observed_seo'),
('matrx-user/marketing-page', 'perf', 'Crawl performance', 'Crawl-time performance evidence from the latest snapshot (response time, payload bytes). Empty when uncrawled. Distinct from PageSpeed Insights lab data.', 'object', false, 150, 650, true, 'observed_seo'),
('matrx-user/marketing-page', 'images', 'Images', 'Observed image evidence from the latest snapshot: total/missing-alt counts plus the per-image inventory (src/srcset, alt, dimensions, loading/decoding/fetch priority, title, featured-image marker). Empty when uncrawled; older snapshots may contain counts only.', 'object', false, 8000, 655, false, 'observed_seo'),
('matrx-user/marketing-page', 'snapshot_captured_at', 'Snapshot captured at', 'ISO timestamp of the latest accepted snapshot — how fresh the observed evidence is. Empty when uncrawled.', 'string', false, 25, 430, true, 'captured_content'),
('matrx-user/marketing-page', 'word_count', 'Word count', 'Word count of the latest snapshot''s main content. Zero/empty when uncrawled.', 'number', false, 6, 440, true, 'captured_content'),
('matrx-user/marketing-page', 'page_content', 'Page content (markdown)', 'The FULL extracted markdown of the page''s latest accepted snapshot — the actual body content the live site serves. Empty when the page has never been captured. This is the primary payload for content analysis, keyword work, and rewriting.', 'document', false, 12000, 450, true, 'captured_content'),
('matrx-user/marketing-page', 'content', 'Primary content', 'Alias of page_content for generic bindings: the full extracted markdown of the latest snapshot. Empty when uncrawled.', 'document', false, 12000, 455, true, 'captured_content'),
('matrx-user/marketing-page', 'content_stats', 'Content stats', 'Quantitative content signals from the latest snapshot: sentence count, Flesch reading ease, link totals (internal/external), and image count plus missing-alt count. Empty when uncrawled.', 'object', false, 250, 470, true, 'captured_content'),
('matrx-user/marketing-page', 'content_file_ids', 'Content file IDs', 'File ids of the stored capture artifacts: { body_file_id (raw HTML), markdown_file_id (extracted markdown) }. Empty when uncrawled; either id may be null when that artifact wasn''t stored.', 'object', false, 110, 480, true, 'captured_content'),
('matrx-user/marketing-page', 'captures', 'Captures', 'Screenshot records for this page as loaded on the workspace, newest first: one entry per capture with kind, file_id, captured_at, width, height, and snapshot_id. Empty array when the page has never been captured visually.', 'array', false, 900, 500, true, 'captures'),
('matrx-user/marketing-page', 'has_desktop_capture', 'Desktop captured', 'True when at least one desktop-sized screenshot exists for this page. False (or absent while captures are still loading) otherwise.', 'boolean', false, 5, 510, true, 'captures'),
('matrx-user/marketing-page', 'has_mobile_capture', 'Mobile captured', 'True when at least one mobile-sized screenshot exists for this page. False (or absent while captures are still loading) otherwise.', 'boolean', false, 5, 520, true, 'captures'),
('matrx-user/marketing-page', 'open_findings', 'Open findings', 'Number of open, non-suppressed analysis findings against this page. Zero when the analysis pipeline has found nothing (or hasn''t run).', 'number', false, 3, 600, true, 'analysis'),
('matrx-user/marketing-page', 'findings', 'Findings', 'The open, non-suppressed analysis findings against this page as listed on the workspace (bounded list): per finding its check, severity, message, and status. Empty array when nothing is open. Complements the open_findings count.', 'array', false, 1200, 605, true, 'analysis'),
('matrx-user/marketing-page', 'page_analyzer', 'Page Analyzer', 'The Page Analyzer agent''s keyword picture for this page: inferred_primary_keyword, supported_keywords, discovered_keywords, content_role, funnel_position, declared_vs_actual, and gaps[]. Empty when the analyzer has not run in this session.', 'object', false, 2000, 610, true, 'analysis'),
('matrx-user/marketing-page', 'page_score', 'Page score', 'Composite check-based score for this page from `v_page_score`. Empty when the page has never been scored.', 'number', false, 5, 620, true, 'analysis'),
('matrx-user/marketing-page', 'failed_checks', 'Failed checks', 'Number of failing checks contributing to the page score. Zero when all checks pass or the page has never been scored.', 'number', false, 3, 630, true, 'analysis'),
('matrx-user/marketing-page', 'gsc_metrics_28d', 'Google Search Console (28d)', 'Rolling 28-day Google Search Console evidence for this page: clicks, impressions, ctr, position. Empty when GSC is not connected or never synced.', 'object', false, 120, 470, true, 'performance'),
('matrx-user/marketing-page', 'gsc_queries', 'GSC top queries', 'Per-query Search Console breakdown for this page over the default 28-day window (bounded list, up to 50 rows, strongest first): per query its clicks, impressions, and average position. The page''s Search Console pane lets the user pick a wider range (90d/12m/all) interactively; this value always reflects the 28-day default. Empty array when GSC is not connected or reports nothing for the window.', 'array', false, 2200, 472, true, 'performance'),
('matrx-user/marketing-page', 'target_performance', 'Target keyword performance', 'How this page ACTUALLY performs for its target keyword, resolved once the target-performance pane has loaded: SERP rank observations (organic + AI-answer targets, each with the exact ranking/cited URL — reveals cannibalization when it''s a different page of the site), Search Console clicks/impressions/position for the query on this page, the site-wide top page for the query, and the latest AI-answer citation evidence. Empty/undefined when no target keyword is set or the pane has not resolved yet in this session.', 'object', false, 1400, 473, true, 'performance'),
('matrx-user/marketing-page', 'inbound_links', 'Inbound internal links', 'Internal pages linking TO this page (bounded list from web.link_edge): per link the source URL and anchor text. Empty array when the crawl found none.', 'array', false, 900, 474, true, 'performance'),
('matrx-user/marketing-page', 'outbound_links', 'Outbound internal links', 'Internal pages this page links OUT to (bounded list from web.link_edge): per link the target URL and anchor text. Empty array when the crawl found none.', 'array', false, 900, 476, true, 'performance'),
('matrx-user/marketing-page', 'backlinks', 'Backlinks', 'External backlink evidence for this page as loaded on the workspace: the latest snapshot totals and top referring rows. Empty when no backlink collection has run.', 'object', false, 1000, 478, true, 'performance'),
('matrx-user/marketing-page', 'pagespeed', 'PageSpeed Insights', 'Latest persisted PageSpeed Insights evidence per strategy (mobile/desktop): Lighthouse category scores, lab LCP/CLS/INP, the CrUX field category, and observed_at. Empty when no collection has run for this page.', 'object', false, 700, 480, true, 'performance'),
('matrx-user/marketing-page', 'ga4_metrics', 'Google Analytics', 'Stored GA4 landing-page totals for this page: sessions, users, engaged sessions, and engagement rate. Empty when GA4 is not connected or no rows are stored.', 'object', false, 150, 490, true, 'performance'),
('matrx-user/marketing-page', 'sitemap_memberships', 'Sitemap memberships', 'Which sitemap documents advertise this canonical URL: one entry per sitemap with its url, lastmod, and last_seen. Empty array when no sitemap advertises the URL.', 'array', false, 400, 495, true, 'performance'),
('matrx-user/marketing-page', 'page_tasks', 'Page tasks', 'Tasks associated with this page (via web_page association edges): per task its title, status, priority, and due date. Empty array when no tasks are linked.', 'array', false, 600, 810, true, 'attachments'),
('matrx-user/marketing-page', 'attached_items', 'Attached items', 'Summary of everything associated with this page (notes, files, conversations, working documents…): counts per entity type from the association edges. Empty when nothing is attached.', 'object', false, 200, 820, true, 'attachments'),
('matrx-user/marketing-page', 'site_context', 'Site context (XML)', 'Compact XML snapshot of the managed website: identity (name, root URL, domain, status, description), connection statuses (Init/GSC/GA4/PSI/CMS), initialization state, and registry counts (canonical pages, open findings, sitemaps, last crawl). Built by buildSiteContextXml (features/marketing/lib/surface-context.ts). Empty during initial load.', 'string', false, 2000, 225, true, 'inherited:matrx-user/marketing-site'),
('matrx-user/marketing-page', 'site_id', 'Site ID', 'UUID of the `web.site` the user is working on. Always present — the route carries it.', 'string', true, 36, 310, true, 'inherited:matrx-user/marketing-site'),
('matrx-user/marketing-page', 'site_name', 'Site name', 'Human name of the managed website (`web.site.name`). Populated once the workspace has loaded; empty during initial load.', 'string', false, 40, 312, true, 'inherited:matrx-user/marketing-site'),
('matrx-user/marketing-page', 'site_root_url', 'Site root URL', 'Root URL of the managed website (e.g. https://example.com). Populated once the workspace has loaded; empty during initial load.', 'string', false, 60, 314, true, 'inherited:matrx-user/marketing-site'),
('matrx-user/marketing-page', 'connection_statuses', 'Connection statuses', 'The five big-picture connection chips derived by features/marketing/lib/site-status.ts — initialized, search_console, analytics, pagespeed, cms — each with state (connected | attention | off) and a human detail line (e.g. a configured GSC binding that has never synced is `attention`, not `connected`). Empty during initial load.', 'object', false, 600, 405, true, 'inherited:matrx-user/marketing-site'),
('matrx-user/marketing-page', 'initialization_state', 'Initialization state', 'Parsed `web.site.initialization` summary (homepage ok, sitemaps found, screenshots captured, discovered totals, per-step errors) written by the scraper initialize command. Empty for a never-initialized site or during initial load.', 'object', false, 500, 415, false, 'inherited:matrx-user/marketing-site'),
('matrx-user/marketing-page', 'open_findings_total', 'Open findings total', 'Number of open, non-suppressed analysis findings across the whole site. Zero when analysis has found nothing (or has not run); empty during initial load.', 'number', false, 4, 635, true, 'inherited:matrx-user/marketing-site'),
('matrx-user/marketing-page', 'pages_total', 'Canonical pages total', 'Count of canonical pages in the site''s registry (`web.page`). Zero for a brand-new site; empty during initial load.', 'number', false, 5, 645, true, 'inherited:matrx-user/marketing-site'),
('matrx-user/marketing-page', 'last_crawl_at', 'Last crawl at', 'ISO timestamp of the site''s most recent crawl session — how fresh the observed evidence is. Empty when the site has never been crawled or during initial load.', 'string', false, 25, 655, true, 'inherited:matrx-user/marketing-site'),
('matrx-user/marketing-page', 'gsc_synced_at', 'GSC last synced at', 'When the site''s Google Search Console collection last completed (`web.site.gsc_synced_at`, ISO timestamp). Empty when GSC is not connected or never synced.', 'string', false, 25, 665, true, 'inherited:matrx-user/marketing-site'),
('matrx-user/marketing-page', 'brand_context', 'Brand context (XML)', 'Compact XML snapshot of the brand this work belongs to: identity (name, industry, description, website) and the editorial brand profile (audience, voice, positioning, offerings, competitors, content guidelines — when the user has authored one) are always embedded once loaded; confirmed business facts, brand assets, social properties, and the managed-site list are included when their data is loaded (always on the brand cockpit; on site pages, when previously fetched). A missing section means NOT LOADED HERE, never that the brand has none. Built by buildBrandContextXml (features/marketing/lib/surface-context.ts). Read this FIRST — it is the ground truth about the client. Empty during initial load.', 'string', false, 2500, 205, true, 'inherited:matrx-user/marketing-brand'),
('matrx-user/marketing-page', 'brand_profile', 'Brand profile (raw)', 'The raw BrandProfile object for agents that want structured access to the editorial profile (audience, voice, positioning, offerings, competitors, content guidelines); the brand_context XML already embeds it. Empty when the user has not authored a profile or during initial load. Bindable only — not auto-shipped.', 'object', false, 800, 215, false, 'inherited:matrx-user/marketing-brand'),
('matrx-user/marketing-page', 'brand_id', 'Brand ID', 'UUID of the `web.brand` row (the anchor entity for this client/company). Always present — the route carries it.', 'string', true, 36, 300, true, 'inherited:matrx-user/marketing-brand'),
('matrx-user/marketing-page', 'brand_name', 'Brand name', 'Display name of the brand. Populated once the workspace has loaded; empty during initial load.', 'string', false, 40, 302, true, 'inherited:matrx-user/marketing-brand'),
('matrx-user/marketing-page', 'pending_review_count', 'Pending review count', 'Number of machine-discovered items awaiting human review in this brand''s discovery inbox. Zero when nothing is pending; empty during initial load.', 'number', false, 3, 605, true, 'inherited:matrx-user/marketing-brand'),
('matrx-user/marketing-page', 'sites_summary', 'Sites summary', 'One row per managed website of this brand: id, name, root_url, and status. Populated once the cockpit''s site list has loaded; empty during initial load or for a brand with no sites yet. Bindable only — not auto-shipped.', 'array', false, 600, 615, false, 'inherited:matrx-user/marketing-brand'),
('matrx-user/marketing-page', 'properties_summary', 'Properties summary', 'One row per non-website brand property (Instagram, Facebook, X, TikTok, YouTube, LinkedIn, Pinterest, Google Business Profile): kind, URL/handle, and status. Empty during initial load or when the brand has no social properties. Bindable only — not auto-shipped.', 'array', false, 600, 625, false, 'inherited:matrx-user/marketing-brand'),
('matrx-user/marketing-page', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-user/marketing-page', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-user/marketing-page', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-user/marketing-page', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-admin/users', 'user_count', 'Total user count', 'Number of accounts currently loaded from `/api/admin/users` into the table (before any client-side search/filter). Zero while the initial fetch is in flight or if it returns no rows.', 'number', true, 5, 100, true, 'roster'),
('matrx-admin/users', 'roster_sample', 'Roster sample', 'The first several loaded accounts, each with { id, email, display_name, admin_level, providers, email_confirmed, onboarding_completed, organizations }, for shape inspection. Bindable, not auto-context — live user PII. Empty array before the first successful load.', 'array', true, 2000, 110, false, 'roster'),
('matrx-admin/users', 'roster_load_error', 'Roster load error', 'The error message from the last failed `/api/admin/users` fetch. Absent when the load succeeded or hasn''t run yet.', 'string', false, 120, 120, true, 'roster'),
('matrx-admin/users', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/users', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/users', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/users', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/users', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-admin/feedback', 'active_tab', 'Active tab', 'Which tab of the Feedback & Announcements console is showing: "feedback" (triage table), "work-queue" (AI agent queue), "announcements", or "categories". Driven by the `?tab=` URL param; defaults to "feedback" when absent. Always present.', 'string', true, 14, 100, true, 'console'),
('matrx-admin/feedback', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/feedback', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/feedback', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/feedback', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/feedback', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-admin/email', 'recipient_mode', 'Recipient mode', '"custom" when the admin is typing raw email addresses, "selected" when picking from the platform user list. Always present.', 'string', true, 8, 100, true, 'recipients'),
('matrx-admin/email', 'custom_emails_raw', 'Custom email addresses', 'The raw comma/newline-separated text in the custom-emails textarea. Empty when recipient_mode is "selected" or the field is untouched.', 'string', false, 120, 110, true, 'recipients'),
('matrx-admin/email', 'selected_user_ids', 'Selected user IDs', 'UUIDs of the platform users checked in the "Selected Users" picker. Preselected from `?userId=` when arriving via the Accounts "Email user" row action. Empty array when recipient_mode is "custom" or nobody is checked.', 'array', false, 200, 120, true, 'recipients'),
('matrx-admin/email', 'subject', 'Subject', 'The email subject line currently in the form. Empty until the admin types one or picks a template.', 'string', false, 60, 200, true, 'compose'),
('matrx-admin/email', 'message_body', 'Message body', 'The plain-text email body currently in the form. Empty until the admin types one or picks a template.', 'string', false, 600, 210, true, 'compose'),
('matrx-admin/email', 'custom_from', 'Custom from address', 'The optional override "From" address/display name typed under Advanced Options. Empty when unset (the default from-address applies).', 'string', false, 40, 220, true, 'compose'),
('matrx-admin/email', 'available_templates', 'Available templates', 'Quick-start email templates loaded from `/api/admin/email`, each with { id, name, subject, message }. Empty array while loading or if none are configured.', 'array', true, 800, 230, false, 'compose'),
('matrx-admin/email', 'is_sending', 'Sending in progress', 'True while a POST to /api/admin/email is in flight. Always present.', 'boolean', true, 5, 240, true, 'compose'),
('matrx-admin/email', 'last_send_result', 'Last send result', 'Outcome of the most recent send attempt: { success, msg }. Absent until the admin has clicked Send at least once this session.', 'object', false, 100, 250, true, 'compose'),
('matrx-admin/email', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/email', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/email', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/email', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/email', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-admin/agent-review', 'queue_row_count', 'Total queue rows', 'Number of rows currently loaded from `agent.review_queue` (up to the 500-row fetch limit), across all statuses. Zero while the initial load is in flight or if the queue is empty.', 'number', true, 4, 100, true, 'queue'),
('matrx-admin/agent-review', 'pending_count', 'Pending count', 'Number of loaded rows with status "pending" — items waiting on the admin''s first look. Always present (0 when none).', 'number', true, 3, 110, true, 'queue'),
('matrx-admin/agent-review', 'changes_requested_count', 'Changes-requested count', 'Number of loaded rows with status "changes_requested" — items where the admin left feedback and is waiting on the originating agent. Always present (0 when none).', 'number', true, 3, 120, true, 'queue'),
('matrx-admin/agent-review', 'approved_count', 'Approved count', 'Number of loaded rows with status "approved" — items the admin signed off on but that are not yet archived. Always present (0 when none).', 'number', true, 3, 130, true, 'queue'),
('matrx-admin/agent-review', 'archived_count', 'Archived count', 'Number of loaded rows with status "archived" — fully handled items, collapsed by default. Always present (0 when none).', 'number', true, 3, 140, true, 'queue'),
('matrx-admin/agent-review', 'show_archived', 'Archived section expanded', 'True when the admin has expanded the collapsed archived section in the UI. Always present.', 'boolean', true, 5, 150, true, 'queue'),
('matrx-admin/agent-review', 'queue_load_error', 'Queue load error', 'The error message from the last failed `agent.review_queue` read. Absent when the load succeeded or hasn''t run yet.', 'string', false, 120, 160, true, 'queue'),
('matrx-admin/agent-review', 'queue_sample', 'Queue sample', 'The first several loaded rows, each with { id, title, url, status, source, instructions, feedback, created_at }, newest first. Bindable, not auto-context — instructions/feedback text adds up fast. Empty array before the first successful load.', 'array', true, 4000, 170, false, 'queue'),
('matrx-admin/agent-review', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/agent-review', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/agent-review', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/agent-review', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/agent-review', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-admin/cx-dashboard', 'dashboard_section', 'Dashboard section', 'Which tab of the CX dashboard is active: "overview", "conversations", "conversation_detail", "requests", "request_detail", "usage", or "errors". Always present — derived from the route.', 'string', true, 18, 100, true, 'dashboard_nav'),
('matrx-admin/cx-dashboard', 'overview_kpis', 'Overview KPIs', 'The full Overview-tab payload: totals (conversations, requests, messages, tool calls), cost/token aggregates, error/pending/max-tokens counts, and the models_used / tool_usage / daily_stats breakdown arrays. Present only on the Overview tab.', 'object', false, 4000, 200, false, 'overview'),
('matrx-admin/cx-dashboard', 'overview_total_conversations', 'Total conversations', 'Overview-tab total conversation count for the current timeframe filter. Present only on the Overview tab.', 'number', false, 6, 210, true, 'overview'),
('matrx-admin/cx-dashboard', 'overview_total_cost', 'Total cost', 'Overview-tab total cost (USD) for the current timeframe filter. Present only on the Overview tab.', 'number', false, 8, 220, true, 'overview'),
('matrx-admin/cx-dashboard', 'overview_error_count', 'Error count', 'Overview-tab count of requests that errored, plus overview_error_rate for the ratio. Present only on the Overview tab.', 'number', false, 5, 230, true, 'overview'),
('matrx-admin/cx-dashboard', 'overview_error_rate', 'Error rate', 'Overview-tab error rate as a 0-1 fraction of total requests. Present only on the Overview tab.', 'number', false, 6, 235, true, 'overview'),
('matrx-admin/cx-dashboard', 'conversation_list_results', 'Conversation list', 'The current page of the Conversations table: one entry per conversation with id, title, status, message_count, model_name, provider, parent_conversation_id, and created_at. Present only on the Conversations list tab.', 'array', false, 3000, 300, false, 'conversations'),
('matrx-admin/cx-dashboard', 'conversation_list_total', 'Conversation list total', 'Total conversation count matching the current filters (across all pages), shown next to the list heading. Present only on the Conversations list tab.', 'number', false, 6, 310, true, 'conversations'),
('matrx-admin/cx-dashboard', 'current_conversation_id', 'Active conversation ID', 'UUID of the conversation shown on the conversation detail page. Absent on the list tab.', 'string', false, 36, 320, true, 'conversations'),
('matrx-admin/cx-dashboard', 'current_conversation', 'Active conversation', 'Summary of the conversation on the detail page: { id, title, status, model_name, provider, message_count, parent_conversation_id, config, variables, overrides, metadata, created_at, updated_at }. Absent on the list tab.', 'object', false, 1200, 325, true, 'conversations'),
('matrx-admin/cx-dashboard', 'current_conversation_messages', 'Active conversation messages', 'Every message in the conversation shown on the detail page, in order, with role, content blocks, and timestamps. Bindable rather than auto-context — can be large. Absent on the list tab; empty array if the conversation has no messages.', 'array', false, 8000, 330, false, 'conversations'),
('matrx-admin/cx-dashboard', 'current_conversation_user_requests', 'Active conversation''s requests', 'User requests belonging to the conversation shown on the detail page, with { id, status, iterations, total_tool_calls, total_cost, total_tokens }. Absent on the list tab; empty array if none exist yet.', 'array', false, 1500, 335, false, 'conversations'),
('matrx-admin/cx-dashboard', 'current_conversation_children', 'Active conversation''s sub-agent children', 'Child conversations forked from the one shown on the detail page (sub-agent runs), with { id, title, model_name, message_count }. Absent on the list tab; empty array if none exist.', 'array', false, 800, 340, false, 'conversations'),
('matrx-admin/cx-dashboard', 'request_list_results', 'Request list', 'The current page of the Requests table: one entry per user request with id, conversation_id, conversation_title, status, finish_reason, iterations, total_tool_calls, total_tokens, total_cost, model_name, created_at. Present only on the Requests list tab.', 'array', false, 3500, 400, false, 'requests'),
('matrx-admin/cx-dashboard', 'request_list_total', 'Request list total', 'Total user-request count matching the current filters (across all pages). Present only on the Requests list tab.', 'number', false, 6, 410, true, 'requests'),
('matrx-admin/cx-dashboard', 'current_request_id', 'Active request ID', 'UUID of the user request shown on the request detail page. Absent on the list tab.', 'string', false, 36, 420, true, 'requests'),
('matrx-admin/cx-dashboard', 'current_user_request', 'Active user request', 'Summary of the user request on the detail page: { id, conversation_id, conversation_title, status, finish_reason, iterations, total_tool_calls, total_input_tokens, total_output_tokens, total_cached_tokens, total_tokens, total_cost, total_duration_ms, api_duration_ms, error, model_name, provider, created_at, completed_at }. Absent on the list tab.', 'object', false, 1200, 425, true, 'requests'),
('matrx-admin/cx-dashboard', 'current_request_api_iterations', 'Active request''s API iterations', 'The individual model-call iterations (`cx_request` rows) that make up the user request on the detail page, each with { iteration, model_name, input_tokens, output_tokens, cached_tokens, cost, api_duration_ms, finish_reason }. Bindable rather than auto-context. Absent on the list tab.', 'array', false, 2500, 430, false, 'requests'),
('matrx-admin/cx-dashboard', 'current_request_tool_calls', 'Active request''s tool calls', 'Tool calls made during the user request on the detail page, each with { tool_name, tool_type, status, is_error, error_type, error_message, arguments, output, cost_usd, duration_ms }. The single most useful value for a debugging agent on this page. Absent on the list tab; empty array if no tools were called.', 'array', false, 4000, 435, false, 'requests'),
('matrx-admin/cx-dashboard', 'current_request_cost_verification', 'Active request''s cost verification', 'Server-computed cost cross-check for the user request on the detail page: whether the stored total_cost matches a recomputation from token counts, and the discrepancy if not (`has_discrepancy`). Absent on the list tab.', 'object', false, 300, 440, false, 'requests'),
('matrx-admin/cx-dashboard', 'usage_analytics', 'Usage analytics', 'The Usage & Cost tab''s full payload: total_requests plus by_day / by_provider / by_model cost and token breakdowns. Present only on the Usage tab.', 'object', false, 3000, 500, false, 'usage'),
('matrx-admin/cx-dashboard', 'usage_total_requests', 'Usage total requests', 'Total API request count backing the Usage tab''s charts for the current filters. Present only on the Usage tab.', 'number', false, 6, 510, true, 'usage'),
('matrx-admin/cx-dashboard', 'error_pending_count', 'Pending (stuck) request count', 'Number of user requests stuck in "pending" status (a known Python-side bug the Errors tab flags explicitly). Present only on the Errors tab.', 'number', false, 5, 600, true, 'errors'),
('matrx-admin/cx-dashboard', 'error_max_tokens_count', 'Max-tokens-hit count', 'Number of requests whose finish_reason is "max_tokens" on the Errors tab. Present only on the Errors tab.', 'number', false, 5, 610, true, 'errors'),
('matrx-admin/cx-dashboard', 'error_request_count', 'Errored request count', 'Number of user requests with a non-null error or status "error" on the Errors tab. Present only on the Errors tab.', 'number', false, 5, 620, true, 'errors'),
('matrx-admin/cx-dashboard', 'error_pending_requests', 'Pending requests', 'The pending (stuck) user requests listed on the Errors tab, each with { id, conversation_title, total_tokens, total_cost, created_at }. Bindable rather than auto-context. Present only on the Errors tab; empty array when none are pending.', 'array', false, 1500, 630, false, 'errors'),
('matrx-admin/cx-dashboard', 'error_tool_calls', 'Tool call errors', 'Tool calls that errored, listed on the Errors tab, each with { tool_name, tool_type, error_type, error_message, created_at }. Bindable rather than auto-context. Present only on the Errors tab; empty array when none exist.', 'array', false, 2000, 635, false, 'errors'),
('matrx-admin/cx-dashboard', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/cx-dashboard', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/cx-dashboard', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/cx-dashboard', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/cx-dashboard', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-admin/server-logs', 'selected_app', 'Selected app', 'App key of the service whose logs are shown, e.g. "ai-dream-server", "scraper-service-dev". Always present — comes from the [app] route segment.', 'string', true, 24, 100, true, 'app_selection'),
('matrx-admin/server-logs', 'selected_app_environment', 'Selected app environment', '"production" or "development" for the selected app, taken from the static app registry. Always present.', 'string', true, 12, 105, true, 'app_selection'),
('matrx-admin/server-logs', 'available_apps', 'Available apps', 'The static catalogue of services the viewer can switch to, each with { key, label, env }. Always present — does not depend on a fetch.', 'array', true, 400, 110, false, 'app_selection'),
('matrx-admin/server-logs', 'requested_line_count', 'Requested line count', 'Number of trailing log lines requested from Coolify for the current fetch (one of a fixed set: 50-10000). Always present.', 'number', true, 5, 200, true, 'fetch_state'),
('matrx-admin/server-logs', 'poll_interval_ms', 'Auto-refresh interval (ms)', 'How often the viewer re-fetches logs automatically; 0 means manual refresh only. Always present.', 'number', true, 6, 210, true, 'fetch_state'),
('matrx-admin/server-logs', 'logs_fetched_at', 'Logs fetched at', 'ISO timestamp of the last successful log fetch. Absent before the first fetch completes.', 'string', false, 25, 220, true, 'fetch_state'),
('matrx-admin/server-logs', 'logs_loading', 'Logs loading', 'True while a log fetch is in flight. Always present.', 'boolean', true, 5, 230, true, 'fetch_state'),
('matrx-admin/server-logs', 'logs_fetch_error', 'Fetch error', 'Error message from the last failed log fetch. Absent when the last fetch succeeded or none has run yet.', 'string', false, 150, 240, true, 'fetch_state'),
('matrx-admin/server-logs', 'log_filters', 'Active log filters', 'The parsed-log filter state applied to the raw text: { levels, categories, urgencies, module, search }, each a selected subset (or "all") of the log-rules enums. Always present — the viewer always has a filter object, even at defaults.', 'object', true, 250, 300, true, 'filters'),
('matrx-admin/server-logs', 'log_noise_excludes', 'Noise exclusion presets', 'Which built-in noise presets are toggled on (cloudFiles, healthChecks, admin, replaySweep, wakeListener, autoIngestListener) — persisted in localStorage across sessions. Always present.', 'object', true, 150, 310, false, 'filters'),
('matrx-admin/server-logs', 'view_mode', 'View mode', 'Layout mode of the log panel — "log-only" or a split/inspector mode alongside the JSON payload viewer. Always present.', 'string', true, 14, 320, true, 'filters'),
('matrx-admin/server-logs', 'visible_log_line_count', 'Visible log line count', 'Number of parsed log lines currently visible after filters are applied. Always present — 0 when nothing matches or no logs are loaded.', 'number', true, 5, 400, true, 'log_view'),
('matrx-admin/server-logs', 'raw_logs', 'Raw log text', 'The unparsed log text returned by the last fetch for the selected app. Bindable only — can be very large; prefer `visible_log_line_count` plus a selected line for targeted questions. Empty before the first fetch.', 'string', false, 20000, 410, false, 'log_view'),
('matrx-admin/server-logs', 'selected_log_line', 'Selected log line', 'The single parsed log line the admin has clicked to inspect: { raw, timestamp, level, module, category, urgency }. Absent when nothing is selected.', 'object', false, 500, 420, true, 'log_view'),
('matrx-admin/server-logs', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/server-logs', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/server-logs', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/server-logs', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/server-logs', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-admin/sandbox', 'sandbox_active_count', 'Active instance count', 'Count of instances currently in a "creating", "starting", "ready", or "running" status among the loaded (filtered) set. Always present — 0 while loading or empty.', 'number', true, 4, 100, true, 'fleet_stats'),
('matrx-admin/sandbox', 'sandbox_total_count', 'Total instance count', 'Count of instances currently loaded (matching the active status filter, up to the 100-row page limit). Always present.', 'number', true, 4, 110, true, 'fleet_stats'),
('matrx-admin/sandbox', 'sandbox_unique_user_count', 'Unique user count', 'Number of distinct user_ids among the loaded instances. Always present.', 'number', true, 4, 120, true, 'fleet_stats'),
('matrx-admin/sandbox', 'sandbox_failed_count', 'Failed instance count', 'Count of instances with status "failed" among the loaded set. Always present.', 'number', true, 4, 130, true, 'fleet_stats'),
('matrx-admin/sandbox', 'sandbox_status_filter', 'Status filter', 'The active status filter chip: "all", or one of creating/starting/ready/running/stopped/failed/expired. Always present — defaults to "all".', 'string', true, 10, 200, true, 'instance_list'),
('matrx-admin/sandbox', 'sandbox_instances', 'Sandbox instances', 'The current page of sandbox instances (up to 100) matching the status filter, each with { id, sandbox_id, user_id, status, created_at, expires_at, tier, container_id, ttl_seconds, hot_path, cold_path }. Bindable rather than auto-context — this is per-user infrastructure data across the whole platform. Empty array when none match.', 'array', true, 6000, 210, false, 'instance_list'),
('matrx-admin/sandbox', 'sandbox_list_loading', 'List loading', 'True while the instance list is being (re)fetched. Always present.', 'boolean', true, 5, 220, true, 'instance_list'),
('matrx-admin/sandbox', 'sandbox_list_error', 'List error', 'Error message from the last failed fetch, stop, or delete action. Absent when the last action succeeded or none has run yet.', 'string', false, 150, 230, true, 'instance_list'),
('matrx-admin/sandbox', 'expanded_sandbox_instance_id', 'Expanded instance ID', 'UUID of the instance row the admin has expanded to see full detail. Absent when no row is expanded.', 'string', false, 36, 300, true, 'instance_detail'),
('matrx-admin/sandbox', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/sandbox', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/sandbox', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/sandbox', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/sandbox', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-admin/official-components', 'page_section', 'Page section', '"list" when the admin is on the /administration/ui/official-components browse grid, "detail" when they are on a single component''s /[componentId] page. Always present — each emitter declares which one it is.', 'string', true, 6, 100, true, 'gallery'),
('matrx-admin/official-components', 'total_component_count', 'Total component count', 'Total number of entries in the static componentList catalogue, regardless of any filter. A constant of the registry — the same on both the list and detail pages.', 'number', true, 3, 105, true, 'gallery'),
('matrx-admin/official-components', 'search_query', 'Search query', 'Text in the list page''s search box (URL `?q=`), matched against component name/description/tags via searchComponents. Empty string when no search is active. Absent on the detail page.', 'string', false, 20, 110, true, 'gallery'),
('matrx-admin/official-components', 'selected_category', 'Selected category', 'The category filter chip selected in the sidebar (URL `?category=`), one of the ComponentCategory slugs (e.g. "buttons", "inputs") or "all". Ignored while a search query is active. Absent on the detail page.', 'string', false, 14, 120, true, 'gallery'),
('matrx-admin/official-components', 'filtered_component_count', 'Filtered component count', 'Number of catalogue entries currently shown in the grid after applying the search query or category filter. Equals total_component_count when neither filter is active. Absent on the detail page.', 'number', false, 3, 130, true, 'gallery'),
('matrx-admin/official-components', 'current_component_id', 'Open component id', 'componentId route param of the entry open on the detail page — its catalogue key, e.g. "matrx-data-table". Absent on the list page.', 'string', false, 24, 200, true, 'component_detail'),
('matrx-admin/official-components', 'current_component_name', 'Open component name', 'Human display name of the open catalogue entry, e.g. "Matrx Data Table". Absent on the list page.', 'string', false, 40, 210, true, 'component_detail'),
('matrx-admin/official-components', 'current_component_description', 'Open component description', 'The catalogue entry''s own description text, as authored in component-list.tsx. Absent on the list page; may be empty if the entry has none.', 'string', false, 160, 220, true, 'component_detail'),
('matrx-admin/official-components', 'current_component_path', 'Open component source path', 'Repo-relative source path of the open component, shown as a code chip under the title. Absent on the list page.', 'string', false, 80, 230, true, 'component_detail'),
('matrx-admin/official-components', 'current_component_categories', 'Open component categories', 'The ComponentCategory slugs the open entry belongs to (a component may have several). Absent on the list page.', 'array', false, 40, 240, true, 'component_detail'),
('matrx-admin/official-components', 'current_component_tags', 'Open component tags', 'Optional free-text tags on the open catalogue entry, used for search matching. Absent on the list page; empty array when the entry has none.', 'array', false, 60, 250, true, 'component_detail'),
('matrx-admin/official-components', 'related_component_count', 'Related component count', 'Number of other catalogue entries shown in the "Related Components" panel (entries sharing at least one category with the open one, capped at 3). Absent on the list page.', 'number', false, 1, 260, true, 'component_detail'),
('matrx-admin/official-components', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/official-components', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/official-components', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/official-components', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/official-components', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline'),
('matrx-admin/applications', 'active_tab', 'Active tab', 'Which tab of the Applications hub is showing: "overview", "configuration", "catalogs", "installations", or "history". Derived from the pathname under /administration/applications. Always present.', 'string', true, 14, 100, true, 'hub'),
('matrx-admin/applications', 'application_count', 'Application count', 'Number of distinct applications known to the hub — the union of apps with a config row, a catalog entry, or an installed instance. Absent outside the Overview tab.', 'number', false, 2, 200, true, 'overview'),
('matrx-admin/applications', 'applications_overview_summary', 'Applications overview summary', 'One entry per known application: app slug, schema version, minimum supported version, config URL/flag counts, catalog totals (total/active/kinds), and fleet totals (total/recent/below-minimum/unreported). Absent outside the Overview tab.', 'array', false, 2000, 210, false, 'overview'),
('matrx-admin/applications', 'fleet_below_minimum_total', 'Fleet below minimum (total)', 'Sum, across every application, of installed instances reporting a version below that application''s published min_supported_app_version — the number the destructive banner names. Absent outside the Overview tab.', 'number', false, 3, 220, true, 'overview'),
('matrx-admin/applications', 'config_row_count', 'Configuration row count', 'Number of app_config rows loaded into the Configuration tab''s table. Absent outside the Configuration tab.', 'number', false, 2, 300, true, 'configuration'),
('matrx-admin/applications', 'config_rows_summary', 'Configuration rows summary', 'One entry per app_config row: app slug, schema_version, min_supported_app_version, updated_at, updated_by. Bindable rather than auto-context — the full config JSONB is not included here. Absent outside the Configuration tab.', 'array', false, 1500, 310, false, 'configuration'),
('matrx-admin/applications', 'config_editor_view', 'Configuration editor view', 'Client-side view mode of the Configuration tab: "list" (table), "edit" (an existing app open in the editor), or "new" (creating a row). Absent outside the Configuration tab.', 'string', false, 5, 320, true, 'configuration'),
('matrx-admin/applications', 'config_editor_app', 'Configuration editor app', 'App slug currently open in the Configuration editor. Empty when config_editor_view is "list" or "new". Absent outside the Configuration tab.', 'string', false, 20, 330, true, 'configuration'),
('matrx-admin/applications', 'catalog_selected_app', 'Catalog selected application', 'App slug the Catalogs tab''s app selector is currently filtered to (defaults to the DEFAULT_CATALOG_APP constant). Absent outside the Catalogs tab.', 'string', false, 20, 400, true, 'catalogs'),
('matrx-admin/applications', 'catalog_entry_count', 'Catalog entry count', 'Number of catalog_entries rows belonging to catalog_selected_app. Absent outside the Catalogs tab.', 'number', false, 3, 410, true, 'catalogs'),
('matrx-admin/applications', 'catalog_kind_summary', 'Catalog kind summary', 'One entry per catalog kind for the selected app: slug, label, registered status, total entries, active entries. Absent outside the Catalogs tab.', 'array', false, 1500, 420, false, 'catalogs'),
('matrx-admin/applications', 'catalog_view', 'Catalog editor view', 'Client-side view mode of the Catalogs tab: "kinds" (dashboard), "kind" (one kind''s table), "edit" (an existing entry open), or "new" (creating an entry). Absent outside the Catalogs tab.', 'string', false, 5, 430, true, 'catalogs'),
('matrx-admin/applications', 'catalog_selected_kind', 'Catalog selected kind', 'Kind slug currently open (catalog_view "kind", "edit", or "new"). Empty when catalog_view is "kinds". Absent outside the Catalogs tab.', 'string', false, 20, 440, true, 'catalogs'),
('matrx-admin/applications', 'catalog_selected_entry_id', 'Catalog selected entry id', 'UUID of the catalog_entries row open in the editor (catalog_view "edit" only). Absent otherwise, and outside the Catalogs tab.', 'string', false, 36, 450, true, 'catalogs'),
('matrx-admin/applications', 'installation_app', 'Installations application', 'The single application the Installations tab''s fleet belongs to (app_instances is single-app; the DEFAULT_APPLICATION constant). Absent outside the Installations tab.', 'string', false, 20, 500, true, 'installations'),
('matrx-admin/applications', 'installation_count', 'Installation count', 'Number of checked-in app_instances rows loaded into the Installations table. Absent outside the Installations tab.', 'number', false, 3, 510, true, 'installations'),
