('matrx-admin/scheduling', 'run_status_filter', 'Run status filter', 'The Runs tab''s status filter: "any", or one of the RunStatus values (queued/claimed/running/success/failed/cancelled/skipped). Absent outside the Runs tab.', 'string', false, 9, 400, true, 'runs'),
('matrx-admin/scheduling', 'run_surface_filter', 'Run surface filter', 'The Runs tab''s originating-surface filter: "any", or one of the Surface enum values. Absent outside the Runs tab.', 'string', false, 20, 410, true, 'runs'),
