('matrx-admin/lookups', 'lookups_tab', 'Active tab', '"clients", "surfaces", or "executors" — which lookup table the admin is editing. Always present.', 'string', true, 10, 100, true, 'lookups_console'),
('matrx-admin/lookups', 'ui_clients_list', 'UI clients', 'Every row loaded from ui_client: name (PK), description, sort_order, is_active. Bindable rather than auto-context.', 'array', true, 800, 110, false, 'lookups_console'),
('matrx-admin/lookups', 'ui_client_count', 'UI client count', 'Number of ui_client rows loaded.', 'number', true, 2, 120, true, 'lookups_console'),
('matrx-admin/lookups', 'ui_surfaces_list', 'UI surfaces (legacy tab)', 'Every row loaded from ui_surface via this legacy quick editor: name (PK), client_name, description, sort_order, is_active. Bindable rather than auto-context. The canonical surface admin is /administration/ui/surfaces — this tab is a lightweight fallback.', 'array', true, 1500, 130, false, 'lookups_console'),
('matrx-admin/lookups', 'ui_surface_count', 'UI surface count (filtered)', 'Number of ui_surface rows currently visible after the client filter is applied.', 'number', true, 3, 140, true, 'lookups_console'),
('matrx-admin/lookups', 'ui_surfaces_client_filter', 'UI surfaces client filter', '"__all__" or a specific ui_client name — filters the UI Surfaces tab table. Always present.', 'string', true, 12, 150, true, 'lookups_console'),
('matrx-admin/lookups', 'tool_executors_list', 'Tool executors', 'Every row loaded from tool_executor: name (PK), description, parent_executor_name, mcp_server_id, is_active, config JSON. Bindable rather than auto-context.', 'array', true, 1500, 160, false, 'lookups_console'),
('matrx-admin/lookups', 'tool_executor_count', 'Tool executor count', 'Number of tool_executor rows loaded.', 'number', true, 3, 170, true, 'lookups_console'),
('matrx-admin/lookups', 'selection', 'Current selection', 'The user''s currently selected text on the surface. Empty string when nothing is selected.', 'string', false, 200, 100, true, 'baseline'),
('matrx-admin/lookups', 'text_before', 'Text before selection', 'Text immediately preceding the selection within the same editable region. Empty when there is no selection or no preceding text.', 'string', false, 500, 110, true, 'baseline'),
('matrx-admin/lookups', 'text_after', 'Text after selection', 'Text immediately following the selection within the same editable region. Empty when there is no selection or no trailing text.', 'string', false, 500, 120, true, 'baseline'),
('matrx-admin/lookups', 'content', 'Primary content', 'The surface''s primary editable content (full document, full note, full file body). Use with care — can be large.', 'string', false, 5000, 200, true, 'baseline'),
('matrx-admin/lookups', 'context', 'Free-form context', 'Loose-shaped context blob a surface may emit (commonly an object with surface-specific keys). Prefer named SurfaceValues over stuffing things in here.', 'object', false, 1000, 9999, true, 'baseline')
INSERT INTO ui.ui_surface_agent_role (surface_name, name, label, description, kind, default_agent_id, max_agents, allow_custom, auto_run, sort_order) VALUES
('matrx-user/marketing-page', 'brand_strategist', 'Brand strategist', 'Advises on the brand''s overall marketing posture across its sites and properties, grounded in confirmed facts and the editorial profile.', 'single', NULL, 1, true, 'user-choice', 100),
('matrx-user/marketing-page', 'profile_author', 'Profile author', 'Drafts and refines the editorial brand profile (audience, voice, positioning, offerings, competitors, content guidelines) from confirmed facts and crawl evidence.', 'single', NULL, 1, true, 'user-choice', 110),
('matrx-user/marketing-page', 'discovery_reviewer', 'Discovery reviewer', 'Recommends confirm/dismiss decisions for machine-discovered candidates awaiting review; never writes confirmed truth directly.', 'single', NULL, 1, true, 'user-choice', 120),
('matrx-user/marketing-page', 'fact_researcher', 'Fact researcher', 'Researches and proposes candidate business facts (contact details, addresses, identity copy) for human confirmation.', 'single', NULL, 1, true, 'user-choice', 130),
('matrx-user/marketing-page', 'site_strategist', 'Site strategist', 'Reads the whole site picture (connections, registry counts, findings, crawl freshness) and recommends what to work on next for this website.', 'single', NULL, 1, true, 'user-choice', 100),
('matrx-user/marketing-page', 'technical_seo_auditor', 'Technical SEO auditor', 'Assesses the site''s technical health from stored evidence (initialization, crawl coverage, findings) and explains issues in plain terms.', 'single', NULL, 1, true, 'user-choice', 110),
('matrx-user/marketing-page', 'setup_assistant', 'Setup assistant', 'Guides the user through completing site setup: initialization, Google Search Console / GA4 / PageSpeed / CMS connections, and first syncs.', 'single', NULL, 1, true, 'user-choice', 120),
('matrx-user/marketing-page', 'metadata_optimizer', 'Metadata optimizer', 'Proposes desired meta title/description candidates for this page, validated against the deterministic SERP limits.', 'single', NULL, 1, true, 'user-choice', 100),
('matrx-user/marketing-page', 'serp_analyst', 'SERP analyst', 'Explains how this page appears in search results and what to change, using observed metrics and GSC evidence.', 'single', NULL, 1, true, 'user-choice', 110),
('matrx-user/marketing-page', 'content_auditor', 'Content auditor', 'Audits the captured page content (headings, word count, readability) against the target keyword.', 'single', NULL, 1, true, 'user-choice', 120),
('matrx-user/marketing-page', 'keyword_strategist', 'Keyword strategist', 'Recommends or refines the target keyword for this page from its content and site context.', 'single', NULL, 1, true, 'user-choice', 130),
('matrx-user/marketing-page', 'image_producer', 'Image producer', 'Generates images for the page''s image plan from a per-image spec (description, alt intent, placement). Must be bound to an agent whose model outputs images; the plan card''s Generate button runs it headlessly and stores the produced file id on the plan entry.', 'single', NULL, 1, true, 'user-choice', 140)
