-- Guard: manifest surfaces missing a ui_surface row
SELECT s.name FROM (VALUES ('matrx-user/marketing-page'), ('matrx-admin/users'), ('matrx-admin/feedback'), ('matrx-admin/email'), ('matrx-admin/agent-review'), ('matrx-admin/cx-dashboard'), ('matrx-admin/server-logs'), ('matrx-admin/sandbox'), ('matrx-admin/official-components'), ('matrx-admin/applications'), ('matrx-admin/scheduling'), ('matrx-admin/agent-apps'), ('matrx-admin/bundles'), ('matrx-admin/mcp-servers'), ('matrx-admin/lookups')) AS s(name) LEFT JOIN ui.ui_surface u ON u.name = s.name WHERE u.name IS NULL;

-- Upsert all manifest values
ON CONFLICT (surface_name, name) DO UPDATE SET label = EXCLUDED.label, description = EXCLUDED.description, value_type = EXCLUDED.value_type, always_available = EXCLUDED.always_available, typical_char_count = EXCLUDED.typical_char_count, sort_order = EXCLUDED.sort_order, auto_context = EXCLUDED.auto_context, group_key = EXCLUDED.group_key, updated_at = now();

-- Upsert all manifest agent roles
ON CONFLICT (surface_name, name) DO UPDATE SET label = EXCLUDED.label, description = EXCLUDED.description, kind = EXCLUDED.kind, default_agent_id = EXCLUDED.default_agent_id, max_agents = EXCLUDED.max_agents, allow_custom = EXCLUDED.allow_custom, auto_run = EXCLUDED.auto_run, sort_order = EXCLUDED.sort_order, updated_at = now();

-- Mirror url_pattern / intro / parent_surface_name (declared fields only)
UPDATE ui.ui_surface SET label = 'Marketing Page Workspace', value_groups = '[{"key":"page_identity","label":"Page identity","sortOrder":100,"description":"Which canonical page this is and its lifecycle standing."},{"key":"page_intent","label":"Page intent","sortOrder":200,"description":"The user''s editorial targets — what this page''s metadata should become."},{"key":"authoring","label":"Authoring","sortOrder":250,"description":"User-authored desired state beyond metadata: draft content, per-area desired values, the keyword batch, and the image plan."},{"key":"observed_seo","label":"Observed SEO","sortOrder":300,"description":"Immutable crawl evidence of what the live site currently serves."},{"key":"captured_content","label":"Captured content","sortOrder":400,"description":"The page body captured by the latest accepted snapshot."},{"key":"captures","label":"Captures","sortOrder":500,"description":"Visual screenshot records of this page (desktop + mobile)."},{"key":"analysis","label":"Analysis","sortOrder":600,"description":"Derived findings and the AI keyword picture for this page."},{"key":"performance","label":"Performance & analytics","sortOrder":700,"description":"Search Console, PageSpeed, and GA4 evidence for this page."},{"key":"attachments","label":"Attachments","sortOrder":800,"description":"Work and resources associated with this page: tasks and attached items."},{"key":"inherited:matrx-user/marketing-site","label":"Inherited from Marketing Site Workspace","sortOrder":9000},{"key":"inherited:matrx-user/marketing-brand","label":"Inherited from Marketing Brand Cockpit","sortOrder":9010},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'verified', readiness_note = NULL, url_pattern = '/marketing/brands/[brandId]/sites/[siteId]/pages/[pageId]', intro = '<surface_intro>
The inherited brand_context and site_context values give you the client and website this page belongs to — read them for framing before working on the page itself.
You are on the Marketing page workspace: one canonical URL of a managed website, with the evidence of what it currently serves and the user''s editorial intent for what it should become.
Two kinds of values live here and must never be confused: OBSERVED values (observed_title, observed_description, observed_seo_metrics) are immutable crawl evidence of the live site; DESIRED values (desired_title, desired_description, desired_seo_metrics) are the user''s editorial targets stored on the page. When asked to improve metadata, you propose DESIRED values — you never alter or invent observed evidence.
Beyond metadata, the surface carries complete crawl evidence: page_identity (featured image, CMS/platform identifiers, author/dates), structured_data (all raw and normalized JSON-LD/microdata/RDFa/microformats), resources (the full declared asset inventory), images, and visual captures. Large raw evidence values remain explicitly bindable but are not auto-added to every agent context. It also carries analysis evidence (Page Analyzer keyword picture, page score, open findings + findings rows), performance evidence (Search Console metrics + the default-28d per-query breakdown in gsc_queries, target_performance — SERP rank + AI-answer citation evidence specifically for the target keyword, PageSpeed Insights, GA4, internal links, backlinks), and the user''s AUTHORING layer: draft_content (the markdown body the page SHOULD have), desired_values (per-area desired state: social card, canonical/robots, heading-structure plan, image plan — each planned image also carries an optional style preset), the keyword_batch (library keywords attached to this page alongside the primary target_keyword), and page_tasks (work linked to this page).
SEO metrics are deterministic (shared pixel-width table between browser and scraper): trust the provided pixel_width / ok flags instead of estimating lengths, and validate any candidate you generate with the seo tool before presenting it.
</surface_intro>', parent_surface_name = 'matrx-user/marketing-site', updated_at = now() WHERE name = 'matrx-user/marketing-page';
UPDATE ui.ui_surface SET label = 'Users & Access — Accounts', value_groups = '[{"key":"roster","label":"Account roster","sortOrder":100,"description":"The user accounts currently loaded and visible in the Accounts table, and the table''s loading/error state."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'stub', readiness_note = 'Manifest-only — no emitter wired. AccountsTableClient.tsx loads the roster into React state but does not mount a SurfaceRuntimeProvider or build an ApplicationScope. Values here describe real page state (user_count, roster_sample, roster_load_error) but nothing currently emits them at runtime.', url_pattern = '/administration/users', intro = '<surface_intro>
This is an ADMIN surface: the Users & Access hub landing tab at /administration/users, the canonical account roster for the whole platform.

One row per Supabase auth user, merged with profile info and admin level, in a sortable/filterable table. user_count is the total loaded; roster_sample is a few rows for shape inspection (bindable only — live account PII).

What you may safely do: summarize the roster, flag accounts needing attention (unconfirmed email, not onboarded, no admin level where expected), and help the admin decide who to contact. You never send an email, magic link, password reset, or in-app message yourself — those are admin button presses on this page, not something you can trigger from context.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/users';
UPDATE ui.ui_surface SET label = 'Feedback & Announcements', value_groups = '[{"key":"console","label":"Feedback console","sortOrder":100,"description":"Which of the four admin tabs the user is currently on."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'stub', readiness_note = 'Manifest-only — no emitter wired. FeedbackManagementContainer.tsx knows the active tab from the URL but has no SurfaceRuntimeProvider. Each tab''s list/detail state (feedback rows, work-queue items, announcements, categories) lives in separate child components (FeedbackTable, WorkQueueTab, AnnouncementTable, CategoriesTab) with no shared scope today — declaring those values would promise data no emitter supplies, so only active_tab is declared for now.', url_pattern = '/administration/users/feedback', intro = '<surface_intro>
This is an ADMIN surface: the Feedback & Announcements console at /administration/users/feedback, a 4-tab admin tool over user-submitted feedback (bugs/features/suggestions), the AI-agent work queue built from that feedback, system announcements, and the feedback category taxonomy.

active_tab tells you which of the four tabs the admin is looking at right now — "feedback" is the full triage table, "work-queue" is the priority-ordered queue agents pull from, "announcements" and "categories" are their own CRUD tabs.

Nothing about a specific feedback item, queue entry, announcement, or category is in scope yet — reason at the level of "what tab is the admin working in" until this surface''s emitter is extended.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/feedback';
UPDATE ui.ui_surface SET label = 'Email Users', value_groups = '[{"key":"recipients","label":"Recipients","sortOrder":100,"description":"Who the email is addressed to: custom typed addresses, or a set of selected platform users."},{"key":"compose","label":"Message","sortOrder":200,"description":"The subject/body being composed, the available templates, and the last send attempt''s outcome."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'stub', readiness_note = 'Manifest-only — no emitter wired. AdminEmailPage (app/(admin)/administration/users/email/page.tsx) holds every value declared here in local useState but has no SurfaceRuntimeProvider mount or ApplicationScope builder.', url_pattern = '/administration/users/email', intro = '<surface_intro>
This is an ADMIN surface: the Email Users compose tool at /administration/users/email, for sending a one-off email to either hand-typed addresses or selected platform users.

recipient_mode tells you whether custom_emails_raw or selected_user_ids is the live recipient list. subject and message_body are the draft; available_templates lists quick-start options the admin can pick from. is_sending is true only while a send POST is in flight; last_send_result reflects the LAST attempt only, never anything current or planned.

What you may safely do: help draft or improve subject/message copy, suggest a template, or reason about the selected recipients. You never send the email yourself — sending is the admin pressing "Send Email".
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/email';
UPDATE ui.ui_surface SET label = 'Agent Review Queue', value_groups = '[{"key":"queue","label":"Review queue","sortOrder":100,"description":"Counts of items in each review status, whether the archived section is expanded, and a sample of loaded rows."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'partial', readiness_note = 'Emitter wired in AgentReviewClient.tsx (counts + a row sample), but not yet browser-verified end to end, so this stays partial rather than verified per the readiness rules.', url_pattern = '/administration/users/agent-review', intro = '<surface_intro>
This is an ADMIN surface: Arman''s Agent Review Queue at /administration/users/agent-review, backed directly by agent.review_queue. Any agent that builds a reviewable demo, route, or UI surface inserts a row here for him to check.

Rows are grouped by status: pending (needs a first look), changes_requested (Arman left feedback, waiting on the agent), approved (signed off), and archived (fully handled, collapsed by default — see show_archived). queue_row_count / pending_count / changes_requested_count / approved_count / archived_count give the shape of the queue at a glance; queue_sample carries a handful of actual rows (title, url, instructions, feedback) for detail.

What you may safely do: help Arman triage — summarize what''s pending, draft feedback text for a row, flag stale items. You never change a row''s status or save feedback yourself; every state transition (Save feedback / Request changes / Approve / Archive / Restore) is Arman''s explicit button press.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/agent-review';
UPDATE ui.ui_surface SET label = 'CX Dashboard', value_groups = '[{"key":"dashboard_nav","label":"Dashboard navigation","sortOrder":100,"description":"Which tab of the CX dashboard the admin is currently on."},{"key":"overview","label":"Overview KPIs","sortOrder":200,"description":"Aggregate metrics shown on the Overview tab: totals, costs, tokens, error rates, per-model and per-tool breakdowns, daily trend."},{"key":"conversations","label":"Conversations","sortOrder":300,"description":"The Conversations list (with its filters) and, on a detail page, the active conversation''s messages, sub-agent children, and user requests."},{"key":"requests","label":"User requests","sortOrder":400,"description":"The Requests list (with its filters) and, on a detail page, the active user request''s API iterations, tool calls, and cost verification."},{"key":"usage","label":"Usage & cost","sortOrder":500,"description":"Usage/cost analytics broken out by day, provider, and model."},{"key":"errors","label":"Errors & issues","sortOrder":600,"description":"Pending (stuck) requests, max-tokens hits, and tool-call errors surfaced on the Errors tab."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'partial', readiness_note = 'dashboard_section is wired everywhere via a base provider in CxDashboardLayoutClient.tsx. The Overview tab additionally emits its full overview_kpis scope via a nested provider in overview-content.tsx (deepest wins). Conversations/requests list+detail, usage, and errors values are declared (THE COMPLETENESS LAW — this IS the data those pages load) but have no emitter yet; each needs the same nested-provider treatment added to its own *-content.tsx.', url_pattern = '/administration/chat/cx-dashboard', intro = '<surface_intro>
This is an ADMIN surface: the CX (customer experience) dashboard at /administration/chat/cx-dashboard, a read-only super-admin console over the cx_* chat tables.

It has five tabs plus two detail pages, all read via dashboard_section: "overview" (aggregate KPIs, cost/token trends, model and tool usage), "conversations" (paginated conversation list) and "conversation_detail" (one conversation''s messages, sub-agent children, and requests), "requests" (paginated user-request list) and "request_detail" (one request''s API iterations, tool calls, and cost verification), "usage" (cost/token analytics by day/provider/model), and "errors" (pending/stuck requests, max-tokens hits, tool-call errors).

Only the values matching the current dashboard_section are populated — everything else is absent, not stale. Treat every row and field here as live production data: summarize, diagnose, and explain it, but never republish it verbatim at scale. You never execute anything on this surface — it has no write path.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/cx-dashboard';
UPDATE ui.ui_surface SET label = 'Server Logs', value_groups = '[{"key":"app_selection","label":"App selection","sortOrder":100,"description":"Which backend service/environment the viewer is showing, and the catalogue of services it can switch between."},{"key":"fetch_state","label":"Fetch state","sortOrder":200,"description":"How many lines were requested, the auto-poll interval, when the log text was last fetched, and any fetch error."},{"key":"filters","label":"Filters & search","sortOrder":300,"description":"The active level/category/urgency/module/search filters and noise-exclusion presets applied to the parsed log lines."},{"key":"log_view","label":"Log content","sortOrder":400,"description":"The parsed log lines currently visible after filtering, and the line (or range) the admin has selected for inspection."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'stub', readiness_note = 'Manifest audited against the live CoolifyLogViewer.tsx state (selectedApp, lineCount, pollInterval, filters, viewMode, selectedLine, rawLogs, fetchedAt, error). No SurfaceRuntimeProvider is wired yet — assembling the scope from that much local state in a 1,400+ line component is a follow-up task, not a drop-in addition.', url_pattern = '/administration/compute/server-logs', intro = '<surface_intro>
This is an ADMIN surface: the super-admin server log viewer at /administration/compute/server-logs/[app], showing live Coolify logs for one backend service (aidream, scraper-service, or matrx-ai, each with a production and development deployment).

The viewer fetches raw log text, parses it into lines with level/category/urgency/module, and lets the admin filter, search, and select a line for JSON-payload inspection. selected_app and selected_app_environment tell you which service/environment you are looking at; log_filters and log_noise_excludes describe what has been narrowed out; visible_log_line_count and selected_log_line describe what is actually on screen.

What you may safely do: read the visible/selected log content and explain errors, summarize patterns, or suggest a better filter or search term. You never execute anything here and cannot restart, deploy, or modify the service being logged.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/server-logs';
UPDATE ui.ui_surface SET label = 'Sandbox Management', value_groups = '[{"key":"fleet_stats","label":"Fleet stats","sortOrder":100,"description":"Summary counts across all sandbox instances currently loaded: active, total, unique users, failed."},{"key":"instance_list","label":"Instance list","sortOrder":200,"description":"The filtered table of sandbox instances, the active status filter, and load/error state."},{"key":"instance_detail","label":"Expanded instance","sortOrder":300,"description":"The single instance row the admin has expanded, if any — its full detail (container, TTL, paths, config)."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'stub', readiness_note = 'Manifest audited against the live AdminSandboxManagementPage state (instances, statusFilter, loading, error, expandedRow, derived stats). No SurfaceRuntimeProvider is wired yet — deferred alongside server-logs; a follow-up pass should add the provider to page.tsx once an agent role for this surface is defined.', url_pattern = '/administration/compute/sandbox', intro = '<surface_intro>
This is an ADMIN surface: the super-admin sandbox fleet console at /administration/compute/sandbox — every on-demand isolated agent-execution instance across every user, not just the current admin''s own.

sandbox_active_count / sandbox_total_count / sandbox_unique_user_count / sandbox_failed_count summarize the currently loaded (filtered) set; sandbox_status_filter tells you which status chip is active; sandbox_instances is the actual row data. expanded_sandbox_instance_id is set when the admin has drilled into one row''s full detail (container id, TTL, hot/cold storage paths, config).

What you may safely do: read this fleet data to diagnose stuck/failed instances, summarize usage across users, or explain a status. Stopping, deleting, or minting SSH access are admin button actions — never assume one happened because it was discussed. SSH credentials are never placed in this surface''s context; they are one-time secret material shown only in the admin''s own dialog.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/sandbox';
UPDATE ui.ui_surface SET label = 'Official Components', value_groups = '[{"key":"gallery","label":"Component gallery","sortOrder":100,"description":"Which page of the library the admin is on, and — on the list page — the search/category filter and how many entries match."},{"key":"component_detail","label":"Component detail","sortOrder":200,"description":"The single catalogue entry open on the detail page: its identity, categorization, description, source path, and related entries."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'stub', readiness_note = 'Manifest-only — no SurfaceRuntimeProvider is mounted on either page yet. Values reflect real page/component state (component-list.tsx + the two page components) but nothing is emitted at runtime today.', url_pattern = '/administration/ui/official-components', intro = '<surface_intro>
This is an ADMIN surface: the Official Component Library registry at /administration/ui/official-components — a gallery of every reusable component the platform ships as "official" (must work on import, never locally restyled).

page_section tells you which page you''re on: "list" is the searchable/category-filtered grid over the static componentList catalogue; "detail" is one component''s own page (its description, source path, live demo, and related components).

On the list page, search_query and selected_category describe the active filter and filtered_component_count / total_component_count give the counts. On the detail page, the current_component_* values describe exactly the one open entry.

What you may safely do: explain a component, suggest related ones from current_component_categories, or help draft catalogue metadata (name, description, tags) for a new entry. componentList is a static in-repo registry, not live application data.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/official-components';
UPDATE ui.ui_surface SET label = 'Applications', value_groups = '[{"key":"hub","label":"Applications hub","sortOrder":100,"description":"Which of the five tabs the admin is currently on."},{"key":"overview","label":"Overview","sortOrder":200,"description":"Per-application summary cards: config/catalog/fleet counts and the below-minimum-version warning."},{"key":"configuration","label":"Configuration","sortOrder":300,"description":"Remote runtime configuration rows (app_config) and which one, if any, is open in the editor."},{"key":"catalogs","label":"Catalogs","sortOrder":400,"description":"Remote catalog entries (catalog_entries) for the selected application, grouped by kind, and the editor view."},{"key":"installations","label":"Installations","sortOrder":500,"description":"The installed fleet (app_instances) and its standing against the live minimum supported version."},{"key":"history","label":"History","sortOrder":600,"description":"The merged configuration + catalog audit timeline and how far back it currently loads."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'partial', readiness_note = 'active_tab has a real emitter (ApplicationsAdminLayoutClient.tsx). Every other value here is real page/component state (AppConfigClient, CatalogsClient, InstallationsClient, ApplicationsHistoryClient, ApplicationsOverview) declared for completeness, but none of it is bridged to the layout''s provider yet — each tab''s data lives in its own client component with no shared scope today. Wiring those requires either lifting state to the layout or mounting a nested SurfaceRuntimeProvider per tab component.', url_pattern = '/administration/applications', intro = '<surface_intro>
This is an ADMIN surface: the Applications hub at /administration/applications — the console governing every shipped Matrx CLIENT (desktop, browser extension, mobile), not user-created agent apps. Five tabs: Overview, Configuration, Catalogs, Installations, History.

active_tab tells you which tab the admin is on right now and is always present. On Overview, applications_overview_summary and fleet_below_minimum_total describe every known application''s config/catalog/fleet standing. On Configuration, config_rows_summary lists the remote runtime config for each application and config_editor_view/config_editor_app say whether one is open for editing. On Catalogs, catalog_kind_summary breaks down remote catalog entries by kind for catalog_selected_app, and catalog_view/catalog_selected_kind/catalog_selected_entry_id track the drill-down. On Installations, the fleet is compared against installation_min_supported_version, with installation_below_min_count naming instances running unsupported builds. On History, history_entry_count and history_fetch_limit describe the merged audit timeline window.

Note: only active_tab is live today — the deeper per-tab values are declared but not yet emitted (see readinessNote). Treat everything past active_tab as "not currently in scope" until the emitter is extended.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/applications';
UPDATE ui.ui_surface SET label = 'Scheduling', value_groups = '[{"key":"hub","label":"Scheduling hub","sortOrder":100,"description":"Which of the seven tabs the admin is currently on."},{"key":"overview","label":"Overview","sortOrder":200,"description":"Cross-platform health counters for the sch_* spine."},{"key":"tasks","label":"Tasks","sortOrder":300,"description":"The task list, its search text, and its enabled filter."},{"key":"runs","label":"Runs","sortOrder":400,"description":"The run list and its status/surface filters."},{"key":"orphan_leases","label":"Orphan leases","sortOrder":500,"description":"Runs whose claim lease expired without completing."},{"key":"cron_tester","label":"Cron tester","sortOrder":600,"description":"The expression/timezone the admin is testing and its validation result."},{"key":"scanner_health","label":"Scanner health","sortOrder":700,"description":"Live status of aidream''s matrx-scheduler scanner process."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'stub', readiness_note = 'Manifest-only — no page in this subtree mounts a SurfaceRuntimeProvider yet. Values reflect real page/component state (Overview''s fetchHealthSummary, Tasks/Runs'' filters and row counts, Orphan leases'' row count, Cron tester''s live validation, Scanner health''s polled status) but nothing is emitted at runtime today. Templates (templates/page.tsx) is a hardcoded in-file SEEDS array with no backing table yet — the page''s own "Coming next" alert says a sch_template table + read RPC are pending — so it is deliberately NOT declared as page data here; declaring it would promise a value no real data source supplies.', url_pattern = '/administration/automation/scheduling', intro = '<surface_intro>
This is an ADMIN surface: the Scheduling admin console at /administration/automation/scheduling — a cross-user, platform-wide view of the sch_* spine (scheduled tasks, their runs, and the scanner that dispatches them).

active_tab tells you which of the tabs the admin is on and is always present. Overview carries platform-wide health counters (task_total_count, task_enabled_count, runs_last_24h_count, failures_last_24h_count, orphan_lease_summary_count). Tasks and Runs carry their own search/filter state plus how many rows are currently loaded. Orphan leases counts runs whose claim lease expired without completing — these should self-heal on the next scanner tick; a persistent nonzero count means something is wrong upstream. Cron tester is a pure client-side validator: cron_expression / cron_timezone / cron_next_fires describe what the admin is testing, not a live schedule. Scanner health mirrors aidream''s live scanner process state (scanner_running, scanner_consecutive_errors, scanner_in_flight_count).

Templates has no backing data source yet (hardcoded starter examples pending a real table) and is deliberately undeclared.

Nothing below active_tab is currently emitted — treat this surface as tab-identity-only until an emitter is wired.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/scheduling';
UPDATE ui.ui_surface SET label = 'Agent Apps Admin', value_groups = '[{"key":"navigation","label":"Navigation","sortOrder":100,"description":"Which sub-route of the agent-apps admin is rendering."},{"key":"dashboard","label":"Dashboard","sortOrder":150,"description":"Aggregate stat-tile counts and the featured / recently-updated app previews on the dashboard."},{"key":"apps_list","label":"Apps list","sortOrder":200,"description":"The full apps table''s filters, sort, and loaded rows on the Apps tab."},{"key":"app_detail","label":"App detail","sortOrder":300,"description":"The single agent app open in the edit/[id] admin shell — its identity, analytics, active tab, and timestamps."},{"key":"categories","label":"Categories","sortOrder":400,"description":"The category list and the category open for editing."},{"key":"executions","label":"Executions & errors","sortOrder":500,"description":"The Executions and Errors tabs: their filters, stats, rows, and the error open in the detail dialog."},{"key":"analytics","label":"Analytics","sortOrder":550,"description":"Platform-wide execution/cost totals and per-app rows."},{"key":"rate_limits","label":"Rate limits","sortOrder":600,"description":"The rate-limit table''s filters, stats, and rows."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'partial', readiness_note = 'Emitters wired for the dashboard (AgentAppsAdminDashboardPage) and apps-list (AgentAppsAdminListPage) sections only. edit/[id], categories, executions, analytics, and rate-limits have no emitter yet — each is its own client component with independent local state and would need its own SurfaceRuntimeProvider mount.', url_pattern = '/administration/agents/agent-apps', intro = '<surface_intro>
This is an ADMIN surface covering the whole Agent Apps admin subtree at /administration/agents/agent-apps/**. It moderates every public agent-backed app on the platform (app.definition rows) — feature/verify/publish status, categories, execution history, per-app analytics, and rate limits.

admin_section tells you which sub-route is rendering: "dashboard" (overview stat tiles + featured/recent app previews), "apps" (the full filterable/sortable apps table), "edit" (one app''s admin + component-code shell), "categories" (the category list/editor), "executions" (execution log + error tabs), "analytics" (platform-wide aggregates), or "rate_limits" (per-identifier execution throttling).

How to read the values: each section''s group (dashboard_*, apps_list_*, selected_app_*, categories_*, executions_*/errors_*, analytics_*, rate_limits_*) is only populated when admin_section matches — everything else on this surface is absent, not stale.

What you may safely do: help the admin draft moderation notes, error resolutions, or category descriptions, summarize analytics or a suspicious rate-limit pattern, and explain what a row means. You never feature, verify, publish, delete, resolve, or unblock anything yourself — those are the admin''s own actions, which call updateAgentAppAdmin / resolveAgentAppError / unblockAgentAppRateLimit.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/agent-apps';
UPDATE ui.ui_surface SET label = 'Bundles Admin', value_groups = '[{"key":"bundle_list","label":"Bundle list","sortOrder":100,"description":"The bundle list, its filter, and the search box."},{"key":"bundle_detail","label":"Bundle detail","sortOrder":200,"description":"The selected bundle''s identity, metadata, and member tools."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'stub', readiness_note = 'Manifest-only — no emitter wired yet. BundlesAdminPage holds list/filter/selection/member state as local useState with no shared scope-building point; wiring a SurfaceRuntimeProvider is a follow-up.', url_pattern = '/administration/agents/bundles', intro = '<surface_intro>
This is an ADMIN surface: the Tool Registry bundles console at /administration/agents/bundles.

A bundle (tool_bundle) groups tools under one "lister" tool an agent can expand on demand — system bundles are platform-wide, personal bundles are owned by one user. The page is master/detail: bundles_list is the left sidebar (filtered by bundles_filter / bundles_search), and selecting a row loads selected_bundle plus its bundle_members.

What you may safely do: help the admin name and describe a bundle, draft short local aliases for member tools, and explain what a bundle''s lister does. You never create, add, remove, or save anything yourself — those are the admin''s own dialog actions.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/bundles';
UPDATE ui.ui_surface SET label = 'MCP Servers Admin', value_groups = '[{"key":"server_list","label":"Server list","sortOrder":100,"description":"The MCP server list and its search box."},{"key":"server_detail","label":"Server detail","sortOrder":200,"description":"The selected server''s identity, sync/test status, active tab, and that tab''s data (tools, configs, connections)."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'stub', readiness_note = 'Manifest-only — no emitter wired yet. McpServersAdminPage and its tab components (ToolsTab/ConfigsTab/ConnectionsTab/MetaTab) hold state as local useState with no shared scope-building point; wiring a SurfaceRuntimeProvider is a follow-up.', url_pattern = '/administration/agents/mcp-servers', intro = '<surface_intro>
This is an ADMIN surface: the Tool Registry MCP servers console at /administration/agents/mcp-servers.

An MCP server (tool_mcp_server) is a connectable Model Context Protocol server the platform can provision tools from. The page is master/detail: mcp_servers_list is the left sidebar (filtered by mcp_search), and selecting a row loads selected_server plus whichever detail tab is active (selected_server_active_tab): tools, configs, connections, or metadata.

What you may safely do: help the admin draft a new server''s description, diagnose a sync error (selected_server.last_sync_error) or a failed connection test (latest_test_result), and explain a config''s transport/env requirements. You never trigger a refresh, test, or save yourself — those are the admin''s own button clicks.

There are no credentials in this scope beyond what is already visible on the page (e.g. npm/pip package names). Env var VALUES for a config are never emitted here, only the schema describing what a user must supply.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/mcp-servers';
UPDATE ui.ui_surface SET label = 'Tool Registry Lookups Admin', value_groups = '[{"key":"lookups_console","label":"Lookups console","sortOrder":100,"description":"Which lookup table tab is active and the rows loaded for each of the three tables."},{"key":"baseline","label":"Generic baselines","sortOrder":9900}]'::jsonb, readiness = 'stub', readiness_note = 'Manifest-only — no emitter wired yet. LookupsAdminPage''s three CRUD sub-components (UiClientCrud/UiSurfaceCrud/ToolExecutorCrud) each hold their own local useState with no shared scope-building point; wiring a SurfaceRuntimeProvider is a follow-up.', url_pattern = '/administration/agents/lookups', intro = '<surface_intro>
This is an ADMIN surface: the Tool Registry lookups console at /administration/agents/lookups.

Three reference tables, one per tab (lookups_tab): ui_client (client apps that can hold surfaces), ui_surface (a legacy quick editor — real surface work belongs on /administration/ui/surfaces), and tool_executor (capability providers a tool can bind to, e.g. mcp.<slug>, aidream, matrx-local).

What you may safely do: help the admin draft a clear name/description for a new client, surface, or executor row, or explain what an existing row is for from its fields. You never create, save, activate, or deactivate a row yourself — those are the admin''s own dialog and toggle actions.
</surface_intro>', updated_at = now() WHERE name = 'matrx-admin/lookups';
